try{$f.Write($raw,0,$raw.Length);$f.Flush($true)}finally{$f.Dispose()}
}
function Rules($a){
return (@($a.GetAccessRules($true,$true,[Security.Principal.SecurityIdentifier])|ForEach-Object{
('{0}|{1}|{2}|{3}|{4}|{5}' -f $_.IdentityReference.Value,[int]$_.FileSystemRights,[int]$_.AccessControlType,$_.IsInherited,[int]$_.InheritanceFlags,[int]$_.PropagationFlags)
}|Sort-Object) -join ';')
}
function Inspect([string]$p){
$i=Get-Item -LiteralPath $p -Force
if($i.PSIsContainer -or ($i.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'regular file only'}
